umask 077; install -d -m 700 /root/branch_stock_credentials; openssl rand -hex 24 > /root/branch_stock_credentials/stock_app.password; openssl rand -hex 24 > /root/branch_stock_credentials/auditor.password; stock_pw=$(cat /root/branch_stock_credentials/stock_app.password); audit_pw=$(cat /root/branch_stock_credentials/auditor.password); sudo -u postgres psql -v ON_ERROR_STOP=1 -v stock_pw="$stock_pw" -v audit_pw="$audit_pw" postgres <<'SQL'
CREATE ROLE stock_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
CREATE ROLE auditor LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
SELECT format('ALTER ROLE stock_app PASSWORD %L', :'stock_pw') \gexec
SELECT format('ALTER ROLE auditor PASSWORD %L', :'audit_pw') \gexec
CREATE DATABASE branch_stock;
SQL
sha256sum /srv/legacy2/database-reader-writer-roles/stock.sql > /tmp/stock.sql.sha256.before; sudo -u postgres psql -v ON_ERROR_STOP=1 -d branch_stock -f /srv/legacy2/database-reader-writer-roles/stock.sql; sudo -u postgres psql -v ON_ERROR_STOP=1 -d branch_stock <<'SQL'
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
GRANT SELECT, UPDATE (quantity) ON TABLE public.stock TO stock_app;
GRANT SELECT ON TABLE public.stock, public.supplier_costs TO auditor;
SQL
sha256sum -c /tmp/stock.sql.sha256.before; printf 'credential files: '; stat -c '%n mode=%a owner=%U:%G size=%s' /root/branch_stock_credentials/*.password

